import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Generates the sample bank statements in ../data from fixed seeds, so they
 * can be regenerated byte for byte:
 *
 *   java tools/GenStatements.java data
 *
 * java.util.Random's algorithm is fixed by its spec, so the same seed gives
 * the same file on every JDK.
 */
public class GenStatements {
    record Payee(String name, int minCents, int maxCents, int perMonth) {}

    // Spending payees (amounts are negated). Names with commas get quoted.
    static final List<Payee> SPENDING = List.of(
        new Payee("Tesco Stores 2841", 850, 6400, 6),
        new Payee("Sainsbury's, Headingley", 1200, 5200, 3),
        new Payee("Lidl GB, Leeds", 700, 3100, 2),
        new Payee("Café Nero", 260, 690, 4),
        new Payee("Pret A Manger", 350, 1150, 2),
        new Payee("Zoë's Bakery", 180, 900, 2),
        new Payee("TfL Travel Charge", 280, 1520, 4),
        new Payee("Northern Trains", 450, 3800, 1),
        new Payee("Łódź Pierogi Bar", 1100, 3400, 1),
        new Payee("東京ラーメン Leeds", 1250, 2600, 1),
        new Payee("Netflix.com", 1099, 1099, 1),
        new Payee("Spotify AB", 1199, 1199, 1),
        new Payee("Boots \"The Chemist\"", 300, 2500, 1),
        new Payee("Amazon Marketplace", 499, 7999, 2),
        new Payee("PureGym Ltd", 2499, 2499, 1),
        new Payee("Yorkshire Water", 3450, 3450, 1));

    public static void main(String[] args) throws IOException {
        Path dir = Path.of(args.length > 0 ? args[0] : "data");
        Files.createDirectories(dir);
        write(dir.resolve("statement_2026q1.csv"), statement(20260101L, YearMonth.of(2026, 1), 3, true), "\n", false);
        write(dir.resolve("statement_winter.csv"), statement(20251101L, YearMonth.of(2025, 11), 4, true), "\r\n", true);
        write(dir.resolve("statement_small.csv"), small(), "\n", false);
    }

    static List<String> statement(long seed, YearMonth first, int months, boolean malformed) {
        Random random = new Random(seed);
        List<String[]> rows = new ArrayList<>(); // {date, csvLine}
        for (int m = 0; m < months; m++) {
            YearMonth month = first.plusMonths(m);
            add(rows, month.atDay(1), "Moorside Lettings", "-950.00");
            add(rows, month.atDay(25), "ACME LTD SALARY", "2480.00");
            add(rows, month.atEndOfMonth(), "Interest, Monthly", "0." + String.format("%02d", 10 + random.nextInt(80)));
            for (Payee p : SPENDING) {
                for (int i = 0; i < p.perMonth(); i++) {
                    int cents = p.minCents() + random.nextInt(p.maxCents() - p.minCents() + 1);
                    LocalDate date = month.atDay(1 + random.nextInt(month.lengthOfMonth()));
                    add(rows, date, p.name(), "-" + money(cents));
                }
            }
            // A refund and a last-day-of-month purchase every month.
            add(rows, month.atDay(10 + random.nextInt(10)), "Amazon Marketplace", money(499 + random.nextInt(3000)));
            add(rows, month.atEndOfMonth(), "Tesco Stores 2841", "-" + money(400 + random.nextInt(2000)));
        }
        rows.sort((a, b) -> a[0].compareTo(b[0])); // stable: same-day rows keep insertion order
        List<String> lines = new ArrayList<>();
        lines.add("date,description,amount");
        for (String[] row : rows) lines.add(row[1]);
        if (malformed) {
            String y = String.valueOf(first.getYear());
            insert(lines, random, y + "-02-30,Tesco Stores 2841,-12.00");          // no such date
            insert(lines, random, first.atDay(14) + ",Card payment,12,50");         // comma in an unquoted amount
            insert(lines, random, first.plusMonths(1).atDay(3) + ",\"Uber, London,-8.20"); // unterminated quote
            insert(lines, random, first.plusMonths(1).atDay(9) + ",Pret A Manger,£4.50");   // currency sign
            insert(lines, random, first.plusMonths(2).atDay(2) + ",,-3.00");        // empty description
        }
        return lines;
    }

    static List<String> small() {
        return List.of(
            "date,description,amount",
            "2026-03-01,Moorside Lettings,-950.00",
            "2026-03-02,Tesco Stores 2841,-23.40",
            "2026-03-02,\"Sainsbury's, Headingley\",-41.15",
            "2026-03-05,Café Nero,-3.10",
            "2026-03-09,TfL Travel Charge,-7.40",
            "2026-03-14,Amazon Marketplace,-24.99",
            "2026-03-18,Amazon Marketplace,24.99",
            "2026-03-25,ACME LTD SALARY,2480.00",
            "2026-03-31,Zoë's Bakery,-4.35",
            "2026-03-31,Tesco Stores 2841,-0.29",
            "2026-04-01,Tesco Stores 2841,-18.00",
            "2026-04-01,Netflix.com,-10.99");
    }

    static void add(List<String[]> rows, LocalDate date, String payee, String amount) {
        rows.add(new String[] {date.toString(), date + "," + quote(payee) + "," + amount});
    }

    static void insert(List<String> lines, Random random, String line) {
        lines.add(2 + random.nextInt(lines.size() - 2), line);
    }

    /** RFC 4180 quoting: only when needed, doubling inner quotes. */
    static String quote(String field) {
        if (!field.contains(",") && !field.contains("\"")) return field;
        return "\"" + field.replace("\"", "\"\"") + "\"";
    }

    static String money(int cents) {
        return (cents / 100) + "." + String.format("%02d", cents % 100);
    }

    static void write(Path path, List<String> lines, String eol, boolean bom) throws IOException {
        String text = (bom ? "﻿" : "") + String.join(eol, lines) + eol;
        Files.writeString(path, text, StandardCharsets.UTF_8);
        System.out.println("wrote " + path + " (" + lines.size() + " lines)");
    }
}
